sys_script.script:
(function executeRule(current, previous) {
    try {
        // Get the complaint text from short_description and/or description
        var shortDesc = current.getValue('short_description') || '';
        var description = current.getValue('description') || '';
        var complaintText = shortDesc + ' ' + description;
        complaintText = complaintText.trim();

        if (!complaintText) {
            return;
        }

        // Instantiate and run the NLP engine
        var engine = new x_2145749_qc.ComplaintNLPEngine();
        var result = engine.analyze(complaintText);

        // Prevent recursive triggers
        current.setWorkflow(false);

        // Only set complaint_type if it's currently empty
        var currentType = current.getValue('x_2145749_qc_complaint_type');
        if (!currentType && result.category && result.category !== 'other') {
            current.setValue('x_2145749_qc_complaint_type', result.category);
        }

        // Always update AI urgency fields
        current.setValue('x_2145749_qc_ai_urgency_score', result.score);
        current.setValue('x_2145749_qc_ai_urgency_level', result.level);
        current.setValue('x_2145749_qc_ai_urgency_reason', result.reason);

        current.update();

        gs.debug('AI Analyze Complaint: Processed case ' + current.getUniqueValue() +
            ' - Category: ' + result.category +
            ', Score: ' + result.score +
            ', Level: ' + result.level);

    } catch (e) {
        gs.error('AI Analyze Complaint: Error processing case ' +
            current.getUniqueValue() + ' - ' + e.message);
    }
})(current, previous);
